"""Canonical, engine-neutral model representation.

The canonical model is intentionally small: it carries the rigid-body data
needed to validate and export a robot model without making URDF, MJCF, Drake,
or MuJoCo the source of truth.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field
from types import MappingProxyType
from typing import Any

from src.shared.python.model_generation.builders.urdf_writer import URDFWriter
from src.shared.python.model_generation.core.types import (
    Geometry,
    GeometryType,
    Inertia,
    Joint,
    JointDynamics,
    JointLimits,
    JointType,
    Link,
    Material,
    Origin,
)
from src.shared.python.model_generation.core.validation import (
    ValidationResult,
    Validator,
)

CANONICAL_MODEL_SCHEMA_VERSION = 1


def _tuple_of_floats(
    values: Iterable[float], *, length: int, field_name: str
) -> tuple[float, ...]:
    result = tuple(float(value) for value in values)
    if len(result) != length:
        raise ValueError(f"{field_name} must contain {length} values")
    return result


def _sorted_mapping(data: dict[str, Any]) -> dict[str, Any]:
    return {key: data[key] for key in sorted(data)}


def _frozen_json_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return MappingProxyType(
            {key: _frozen_json_value(value[key]) for key in sorted(value)}
        )
    if isinstance(value, tuple | list):
        return tuple(_frozen_json_value(item) for item in value)
    return value


def _canonical_json_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {key: _canonical_json_value(value[key]) for key in sorted(value)}
    if isinstance(value, tuple | list):
        return [_canonical_json_value(item) for item in value]
    return value


def _geometry_type_value(geometry_type: str | GeometryType) -> str:
    if isinstance(geometry_type, GeometryType):
        return geometry_type.value
    return str(geometry_type)


def _joint_type_value(joint_type: str | JointType) -> str:
    if isinstance(joint_type, JointType):
        return joint_type.value
    return str(joint_type)


@dataclass(frozen=True)
class CanonicalOrigin:
    """Position and roll-pitch-yaw orientation in a parent frame."""

    xyz: tuple[float, float, float] = (0.0, 0.0, 0.0)
    rpy: tuple[float, float, float] = (0.0, 0.0, 0.0)

    def __post_init__(self) -> None:
        object.__setattr__(
            self, "xyz", _tuple_of_floats(self.xyz, length=3, field_name="xyz")
        )
        object.__setattr__(
            self, "rpy", _tuple_of_floats(self.rpy, length=3, field_name="rpy")
        )

    @classmethod
    def from_core(cls, origin: Origin) -> CanonicalOrigin:
        return cls(xyz=origin.xyz, rpy=origin.rpy)

    def to_core(self) -> Origin:
        return Origin(xyz=self.xyz, rpy=self.rpy)

    def to_dict(self) -> dict[str, Any]:
        return {"xyz": list(self.xyz), "rpy": list(self.rpy)}


@dataclass(frozen=True)
class CanonicalInertia:
    """Mass, center of mass, and symmetric inertia tensor components."""

    mass: float
    ixx: float
    iyy: float
    izz: float
    ixy: float = 0.0
    ixz: float = 0.0
    iyz: float = 0.0
    center_of_mass: tuple[float, float, float] = (0.0, 0.0, 0.0)

    def __post_init__(self) -> None:
        for field_name in ("mass", "ixx", "iyy", "izz", "ixy", "ixz", "iyz"):
            object.__setattr__(self, field_name, float(getattr(self, field_name)))
        object.__setattr__(
            self,
            "center_of_mass",
            _tuple_of_floats(
                self.center_of_mass, length=3, field_name="center_of_mass"
            ),
        )

    @classmethod
    def from_core(cls, inertia: Inertia) -> CanonicalInertia:
        return cls(
            mass=inertia.mass,
            ixx=inertia.ixx,
            iyy=inertia.iyy,
            izz=inertia.izz,
            ixy=inertia.ixy,
            ixz=inertia.ixz,
            iyz=inertia.iyz,
            center_of_mass=inertia.center_of_mass,
        )

    def to_core(self) -> Inertia:
        return Inertia(
            ixx=self.ixx,
            iyy=self.iyy,
            izz=self.izz,
            ixy=self.ixy,
            ixz=self.ixz,
            iyz=self.iyz,
            mass=self.mass,
            center_of_mass=self.center_of_mass,
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "mass": self.mass,
            "ixx": self.ixx,
            "iyy": self.iyy,
            "izz": self.izz,
            "ixy": self.ixy,
            "ixz": self.ixz,
            "iyz": self.iyz,
            "center_of_mass": list(self.center_of_mass),
        }


@dataclass(frozen=True)
class CanonicalMaterial:
    """Visual material metadata shared by exporters."""

    name: str
    color: tuple[float, float, float, float] = (0.8, 0.8, 0.8, 1.0)
    texture: str | None = None

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("material name must be a non-empty string")
        object.__setattr__(
            self, "color", _tuple_of_floats(self.color, length=4, field_name="color")
        )

    @classmethod
    def from_core(cls, material: Material) -> CanonicalMaterial:
        return cls(name=material.name, color=material.color, texture=material.texture)

    def to_core(self) -> Material:
        return Material(name=self.name, color=self.color, texture=self.texture)

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {"name": self.name, "color": list(self.color)}
        if self.texture is not None:
            result["texture"] = self.texture
        return result


@dataclass(frozen=True)
class CanonicalGeometry:
    """Engine-neutral geometry descriptor."""

    geometry_type: str | GeometryType
    dimensions: tuple[float, ...] = ()
    mesh_filename: str | None = None
    mesh_scale: tuple[float, float, float] = (1.0, 1.0, 1.0)

    def __post_init__(self) -> None:
        geometry_type = _geometry_type_value(self.geometry_type)
        GeometryType(geometry_type)
        object.__setattr__(self, "geometry_type", geometry_type)
        object.__setattr__(
            self, "dimensions", tuple(float(value) for value in self.dimensions)
        )
        object.__setattr__(
            self,
            "mesh_scale",
            _tuple_of_floats(self.mesh_scale, length=3, field_name="mesh_scale"),
        )

    @classmethod
    def from_core(cls, geometry: Geometry) -> CanonicalGeometry:
        return cls(
            geometry_type=geometry.geometry_type.value,
            dimensions=geometry.dimensions,
            mesh_filename=geometry.mesh_filename,
            mesh_scale=geometry.mesh_scale,
        )

    def to_core(self) -> Geometry:
        return Geometry(
            geometry_type=GeometryType(self.geometry_type),
            dimensions=self.dimensions,
            mesh_filename=self.mesh_filename,
            mesh_scale=self.mesh_scale,
        )

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {
            "type": self.geometry_type,
            "dimensions": list(self.dimensions),
        }
        if self.mesh_filename is not None:
            result["mesh_filename"] = self.mesh_filename
            result["mesh_scale"] = list(self.mesh_scale)
        return result

    def validate(self, component: str) -> ValidationResult:
        result = ValidationResult(is_valid=True)
        expected_dimensions = {
            GeometryType.BOX.value: 3,
            GeometryType.CYLINDER.value: 2,
            GeometryType.SPHERE.value: 1,
            GeometryType.CAPSULE.value: 2,
        }
        geometry_type = _geometry_type_value(self.geometry_type)
        expected = expected_dimensions.get(geometry_type)
        if expected is not None and len(self.dimensions) != expected:
            result.add_error(
                "CANONICAL_GEOMETRY_DIMENSIONS",
                f"{self.geometry_type} geometry requires {expected} dimensions",
                component,
            )
        if any(dimension <= 0.0 for dimension in self.dimensions):
            result.add_error(
                "CANONICAL_GEOMETRY_NON_POSITIVE",
                "geometry dimensions must be positive",
                component,
            )
        if self.geometry_type == GeometryType.MESH.value and not self.mesh_filename:
            result.add_error(
                "CANONICAL_GEOMETRY_MESH_FILENAME",
                "mesh geometry requires mesh_filename",
                component,
            )
        if any(scale <= 0.0 for scale in self.mesh_scale):
            result.add_error(
                "CANONICAL_GEOMETRY_MESH_SCALE",
                "mesh_scale values must be positive",
                component,
            )
        return result


