@dataclass(frozen=True)
class CanonicalLink:
    """Canonical rigid body node."""

    name: str
    inertia: CanonicalInertia
    visual_geometry: CanonicalGeometry | None = None
    visual_origin: CanonicalOrigin = field(default_factory=CanonicalOrigin)
    visual_material: CanonicalMaterial | None = None
    collision_geometry: CanonicalGeometry | None = None
    collision_origin: CanonicalOrigin = field(default_factory=CanonicalOrigin)

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("link name must be a non-empty string")

    @classmethod
    def from_core(cls, link: Link) -> CanonicalLink:
        return cls(
            name=link.name,
            inertia=CanonicalInertia.from_core(link.inertia),
            visual_geometry=(
                CanonicalGeometry.from_core(link.visual_geometry)
                if link.visual_geometry is not None
                else None
            ),
            visual_origin=CanonicalOrigin.from_core(link.visual_origin),
            visual_material=(
                CanonicalMaterial.from_core(link.visual_material)
                if link.visual_material is not None
                else None
            ),
            collision_geometry=(
                CanonicalGeometry.from_core(link.collision_geometry)
                if link.collision_geometry is not None
                else None
            ),
            collision_origin=CanonicalOrigin.from_core(link.collision_origin),
        )

    def to_core(self) -> Link:
        return Link(
            name=self.name,
            inertia=self.inertia.to_core(),
            visual_geometry=(
                self.visual_geometry.to_core()
                if self.visual_geometry is not None
                else None
            ),
            visual_origin=self.visual_origin.to_core(),
            visual_material=(
                self.visual_material.to_core()
                if self.visual_material is not None
                else None
            ),
            collision_geometry=(
                self.collision_geometry.to_core()
                if self.collision_geometry is not None
                else None
            ),
            collision_origin=self.collision_origin.to_core(),
        )

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {
            "name": self.name,
            "inertia": self.inertia.to_dict(),
            "visual_origin": self.visual_origin.to_dict(),
            "collision_origin": self.collision_origin.to_dict(),
        }
        if self.visual_geometry is not None:
            result["visual_geometry"] = self.visual_geometry.to_dict()
        if self.visual_material is not None:
            result["visual_material"] = self.visual_material.to_dict()
        if self.collision_geometry is not None:
            result["collision_geometry"] = self.collision_geometry.to_dict()
        return result


@dataclass(frozen=True)
class CanonicalJoint:
    """Canonical edge connecting parent and child links."""

    name: str
    joint_type: str | JointType
    parent: str
    child: str
    origin: CanonicalOrigin = field(default_factory=CanonicalOrigin)
    axis: tuple[float, float, float] = (0.0, 0.0, 1.0)
    limits: CanonicalJointLimits | None = None
    dynamics: CanonicalJointDynamics = field(default_factory=CanonicalJointDynamics)

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("joint name must be a non-empty string")
        if not self.parent.strip():
            raise ValueError("joint parent must be a non-empty string")
        if not self.child.strip():
            raise ValueError("joint child must be a non-empty string")
        joint_type = _joint_type_value(self.joint_type)
        JointType(joint_type)
        object.__setattr__(self, "joint_type", joint_type)
        object.__setattr__(
            self, "axis", _tuple_of_floats(self.axis, length=3, field_name="axis")
        )

    @classmethod
    def from_core(cls, joint: Joint) -> CanonicalJoint:
        return cls(
            name=joint.name,
            joint_type=joint.joint_type.value,
            parent=joint.parent,
            child=joint.child,
            origin=CanonicalOrigin.from_core(joint.origin),
            axis=joint.axis,
            limits=(
                CanonicalJointLimits.from_core(joint.limits)
                if joint.limits is not None
                else None
            ),
            dynamics=CanonicalJointDynamics.from_core(joint.dynamics),
        )

    def to_core(self) -> Joint:
        return Joint(
            name=self.name,
            joint_type=JointType(self.joint_type),
            parent=self.parent,
            child=self.child,
            origin=self.origin.to_core(),
            axis=self.axis,
            limits=self.limits.to_core() if self.limits is not None else None,
            dynamics=self.dynamics.to_core(),
        )

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {
            "name": self.name,
            "type": self.joint_type,
            "parent": self.parent,
            "child": self.child,
            "origin": self.origin.to_dict(),
            "axis": list(self.axis),
            "dynamics": self.dynamics.to_dict(),
        }
        if self.limits is not None:
            result["limits"] = self.limits.to_dict()
        return result


@dataclass(frozen=True)
class CanonicalModel:
    """Immutable robot model source of truth for multiple exporters."""

    name: str
    links: tuple[CanonicalLink, ...]
    joints: tuple[CanonicalJoint, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)
    schema_version: int = CANONICAL_MODEL_SCHEMA_VERSION

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("model name must be a non-empty string")
        if self.schema_version != CANONICAL_MODEL_SCHEMA_VERSION:
            raise ValueError(
                f"unsupported canonical model schema_version: {self.schema_version}"
            )
        object.__setattr__(
            self, "links", tuple(sorted(self.links, key=lambda x: x.name))
        )
        object.__setattr__(
            self, "joints", tuple(sorted(self.joints, key=lambda x: x.name))
        )
        object.__setattr__(
            self,
            "metadata",
            _frozen_json_value(_sorted_mapping(dict(self.metadata))),
        )

    @classmethod
    def from_core(
        cls,
        *,
        name: str,
        links: Iterable[Link],
        joints: Iterable[Joint] = (),
        metadata: dict[str, Any] | None = None,
    ) -> CanonicalModel:
        return cls(
            name=name,
            links=tuple(CanonicalLink.from_core(link) for link in links),
            joints=tuple(CanonicalJoint.from_core(joint) for joint in joints),
            metadata=metadata or {},
        )

    def to_core(self) -> tuple[list[Link], list[Joint]]:
        return (
            [link.to_core() for link in self.links],
            [joint.to_core() for joint in self.joints],
        )

    def validate(self, *, strict: bool = True) -> ValidationResult:
        result = ValidationResult(is_valid=True)
        if not self.links:
            result.add_error(
                "CANONICAL_MODEL_EMPTY",
                "canonical model must contain at least one link",
                self.name,
            )
            return result
        for link in self.links:
            for label, geometry in (
                ("visual_geometry", link.visual_geometry),
                ("collision_geometry", link.collision_geometry),
            ):
                if geometry is not None:
                    result.merge(geometry.validate(f"{link.name}.{label}"))
        links, joints = self.to_core()
        result.merge(Validator.validate_model(links, joints, strict=strict))
        return result

    def require_valid(self, *, strict: bool = True) -> None:
        result = self.validate(strict=strict)
        if not result.is_valid:
            raise ValueError("; ".join(result.get_error_messages()))

    def to_urdf(self, *, pretty_print: bool = True, validate: bool = True) -> str:
        if validate:
            self.require_valid()
        links, joints = self.to_core()
        return URDFWriter(pretty_print=pretty_print).write(self.name, links, joints)

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "name": self.name,
            "links": [link.to_dict() for link in self.links],
            "joints": [joint.to_dict() for joint in self.joints],
            "metadata": _canonical_json_value(self.metadata),
        }

    def to_json(self) -> str:
        return json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )

    def stable_hash(self) -> str:
        return hashlib.sha256(self.to_json().encode("utf-8")).hexdigest()
